template<typename T, const unsigned LEN, const unsigned INCREMENT, const unsigned VECDIM>
void mulVS(adf::input_buffer<T>& __restrict in1, adf::input_buffer<T>& __restrict in2, adf::output_buffer<T>& __restrict out);
