29	
30	/* non-vectorization version
31	template<class T>
32	void __attribute__((noinline)) fun_UpdatingDelay_line(
33	    adf::output_buffer<T>& __restrict out_delay,
34	    para_Delay<T> &param,
35	    adf::input_buffer<T>& __restrict in_img_x,
36	    adf::input_buffer<T>& __restrict in_img_z
