40	    T* p_in_delay_img_z = in_img_z.data();
41	
42	    for(int n = 0; n < LEN_OUT; n++)
43	    {//for sample
44	        T acc_sample1 = 0;
45	        T acc_sample2 = 0;
46	
47	        // DIM_X
48	        T diff1 = p_in_delay_img_x[n] - p_const->tx_ref_point_x;
49	        acc_sample1 = acc_sample1 + diff1 * p_const->tileVApo_x;
50	        T diff2 = p_in_delay_img_x[n] - p_const->focal_point_x;
51	        acc_sample2 = acc_sample2 + diff2 * diff2;
52	        // DIM_Z
53	        diff1 = p_in_delay_img_z[n] - p_const->tx_ref_point_z;
54	        acc_sample1 = acc_sample1 + diff1 * p_const->tileVApo_z;
55	        diff2 = p_in_delay_img_z[n] - p_const->focal_point_z;
56	        acc_sample2 = acc_sample2 + diff2 * diff2;
57	
58	        acc_sample1 = aie::abs(acc_sample1) - p_const->tx_delay_distance;
59	        int sign = acc_sample1 >= 0 ? 1 : -1;
60	
61	        acc_sample2 = sign * aie::sqrt(acc_sample2) + p_const->tx_delay_distance_;
62	        p_out_delay[n] = acc_sample2 * p_const->inverse_speed_of_sound - p_const->t_start;
63	    }
64	
65	};
66	*/
67	
68	template <class T, int LEN_IN_delay_t, int LEN_OUT_delay_t, int VECDIM_delay_t>
69	void __attribute__((noinline))
70	kfun_UpdatingDelay_line(adf::output_buffer<T, adf::extents<LEN_OUT_delay_t> >& __restrict out_delay,
71	                        us::L1::para_delay_t<T>* p_const,
72	                        adf::input_buffer<T, adf::extents<LEN_IN_delay_t> >& __restrict in_img_x,
73	                        adf::input_buffer<T, adf::extents<LEN_IN_delay_t> >& __restrict in_img_z) {
74	    T* p_out_delay = out_delay.data();
75	    T* p_in_delay_img_x = in_img_x.data();
76	    T* p_in_delay_img_z = in_img_z.data();
77	
78	    // input and output
79	    aie::vector<T, VECDIM_delay_t> v_img_x, v_img_z;
80	    aie::vector<T, VECDIM_delay_t> v_delay;
81	
82	    // parameter
83	    auto v_ref_x = aie::broadcast<T, VECDIM_delay_t>(p_const->tx_ref_point_x);
84	    auto v_ref_z = aie::broadcast<T, VECDIM_delay_t>(p_const->tx_ref_point_z);
85	    auto v_til_x = aie::broadcast<T, VECDIM_delay_t>(p_const->tileVApo_x);
86	    auto v_til_z = aie::broadcast<T, VECDIM_delay_t>(p_const->tileVApo_z);
87	    auto v_foc_x = aie::broadcast<T, VECDIM_delay_t>(p_const->focal_point_x);
88	    auto v_foc_z = aie::broadcast<T, VECDIM_delay_t>(p_const->focal_point_z);
89	    auto v_dis_0 = aie::broadcast<T, VECDIM_delay_t>(p_const->tx_delay_distance);
90	    auto v_dis_1 = aie::broadcast<T, VECDIM_delay_t>(p_const->tx_delay_distance_);
91	    auto v_speed = aie::broadcast<T, VECDIM_delay_t>(p_const->inverse_speed_of_sound);
92	    auto v_start = aie::broadcast<T, VECDIM_delay_t>(p_const->t_start);
93	    auto v_zeros = aie::broadcast<T, VECDIM_delay_t>(0.0);
94	
95	    aie::vector<T, VECDIM_delay_t> v_sign;
96	    aie::vector<T, VECDIM_delay_t> v_sample1, v_sample2;
97	
98	    aie::vector<T, VECDIM_delay_t> v_diff1, v_diff2;
99	    aie::vector<T, VECDIM_delay_t> acc_sample1, acc_sample2;
100	
101	    for (int n = 0; n < p_const->num_dep_seg; n += VECDIM_delay_t) chess_prepare_for_pipelining {
102	            v_img_x = aie::load_v<VECDIM_delay_t>(p_in_delay_img_x);
103	            p_in_delay_img_x += VECDIM_delay_t;
104	            v_img_z = aie::load_v<VECDIM_delay_t>(p_in_delay_img_z);
105	            p_in_delay_img_z += VECDIM_delay_t;
106	
107	            // DIM_X
108	            v_diff1 = v_img_x - v_ref_x;
109	            acc_sample1 = aie::mul(v_diff1, v_til_x);
110	            v_diff2 = v_img_x - v_foc_x;
111	            acc_sample2 = aie::mul(v_diff2, v_diff2);
112	            // DIM_Z
113	            v_diff1 = v_img_z - v_ref_z;
114	            acc_sample1 = aie::mul(v_diff1, v_til_z) + acc_sample1;
115	            v_diff2 = v_img_z - v_foc_z;
116	            acc_sample2 = aie::mul(v_diff2, v_diff2) + acc_sample2;
117	            acc_sample1 = aie::abs(acc_sample1) - v_dis_0;
118	
119	            auto msk_lt = acc_sample1 < v_zeros;
120	            auto v_sqrt = aie::sqrt(acc_sample2);
121	            v_sign = aie::select(v_sqrt, aie::neg(v_sqrt), msk_lt);
122	
123	            acc_sample2 = v_sign + v_dis_1;
124	            v_delay = aie::mul(acc_sample2, v_speed) - v_start;
125	
126	            aie::store_v(p_out_delay, v_delay);
127	            p_out_delay += VECDIM_delay_t;
